function rampartSimulate(createStrategy, seed, maxTicks) {
  "use strict";
  var REC = rampartSimulate.recorder || null;   // optional per-tick observer (read-only), unused by graders
  var AIRLEN = rampartSimulate.__airLen || 0;    // dev-only switch, removed in final

  // ---------- board ----------
  var GROUND = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR = [[0, 6], [21, 6], [21, 11], [23, 11]];
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];

  function buildRoute(pts) {
    var xs = [], ys = [], i, k, n = 0;
    for (i = 0; i + 1 < pts.length; i++) {
      var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50;
      var bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      var len = Math.abs(bx - ax) + Math.abs(by - ay);
      var sx = bx > ax ? 1 : (bx < ax ? -1 : 0), sy = by > ay ? 1 : (by < ay ? -1 : 0);
      for (k = 0; k < len; k++) { xs[n] = ax + sx * k; ys[n] = ay + sy * k; n++; }
      if (i + 2 === pts.length) { xs[n] = bx; ys[n] = by; }
    }
    return { len: n, xs: xs, ys: ys };
  }
  var ROUTES = [buildRoute(GROUND), buildRoute(AIR)];
  if (AIRLEN) ROUTES[1].len = AIRLEN;

  // ---------- tables ----------
  var TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TIDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  //            cost dmg period range splash slow pierce ground air
  var TDEF = [
    [50, 26, 8, 300, 0, 0, 0, 1, 1],
    [90, 60, 24, 260, 90, 0, 0, 1, 0],
    [70, 10, 12, 240, 0, 30, 0, 1, 1],
    [120, 180, 36, 360, 0, 0, 1, 1, 0],
    [80, 40, 10, 320, 70, 0, 0, 0, 1]
  ];
  var ENAMES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  //            hp speed bounty leak air firstWave weight
  var EDEF = [
    [60, 10, 4, 1, 0, 1, 10],
    [40, 20, 4, 1, 0, 2, 4],
    [50, 12, 6, 2, 1, 3, 3],
    [150, 6, 9, 3, 0, 4, 3],
    [90, 8, 6, 2, 0, 6, 2],
    [70, 8, 7, 2, 0, 8, 1],
    [0, 12, 1, 1, 0, 0, 0]
  ];

  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }

  var rng = mulberry32(seed);
  var mult = [0, 1000];
  function hpMult(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  function armourOf(type, w) { return type === 0 ? Math.floor(w / 4) : (type === 3 ? 6 + w : 0); }

  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], total = 0, t, i;
    for (t = 0; t < 6; t++) if (EDEF[t][5] <= w) total += EDEF[t][6];
    for (i = 0; i < n; i++) {
      var r = rng() % total;
      for (t = 0; t < 6; t++) {
        if (EDEF[t][5] > w) continue;
        if (r < EDEF[t][6]) break;
        r -= EDEF[t][6];
      }
      out.push(t);
    }
    return out;
  }

  // ---------- state ----------
  var strategy = createStrategy();
  var hasTarget = strategy && typeof strategy.target === "function";
  var gold = 250, baseHp = 10, wave = 0, nextId = 1;
  var turrets = [];            // per slot: null | {slot,type,tier,spent,cd,dmg,range,x,y}
  var enemies = [];            // ascending id
  var queue = [];              // {tick,wave,idx,type}, ordered by tick, wave, idx
  var qHead = 0;
  var log = [];
  var fallTick = -1;
  var s, i;
  for (s = 0; s < 16; s++) turrets.push(null);
  var waves = [null, genWave(1)];   // waves[w] = composition (type indices)

  function tierDamage(type, tier) { var d = TDEF[type][1]; for (var k = 1; k < tier; k++) d = Math.floor(d * 16 / 10); return d; }

  function view(e) {
    return { id: e.id, type: ENAMES[e.type], hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air,
      armor: e.armor, speed: e.speed, slowed: e.slow, remaining: e.len - e.progress };
  }

  function spawnEnemy(type, w, progress, maxHp) {
    var d = EDEF[type], route = ROUTES[d[4]];
