      x: route.xs[progress], y: route.ys[progress], air: d[4], armor: armourOf(type, w), speed: d[1],
      slow: 0, age: 0, len: route.len, dead: false };
    enemies.push(e);
    if (REC && REC.spawn) REC.spawn(tick, e);
    return e;
  }

  function applyActions(actions) {
    if (!actions || typeof actions.length !== "number") return;
    var n = Math.min(32, actions.length);
    for (var k = 0; k < n; k++) {
      var a = actions[k];
      if (!a || typeof a !== "object") continue;
      var sl = a.slot;
      if (typeof sl !== "number" || sl !== Math.floor(sl) || sl < 0 || sl > 15) continue;
      var t = turrets[sl];
      if (a.op === "build") {
        if (t) continue;
        var ti = TIDX.hasOwnProperty(a.type) ? TIDX[a.type] : -1;
        if (ti < 0) continue;
        var cost = TDEF[ti][0];
        if (gold < cost) continue;
        gold -= cost;
        turrets[sl] = { slot: sl, type: ti, tier: 1, spent: cost, cd: 0, dmg: TDEF[ti][1], range: TDEF[ti][3],
          x: SLOTS[sl][0] * 100 + 50, y: SLOTS[sl][1] * 100 + 50 };
        log.push([tick, "B", sl, ti]);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        var uc = TDEF[t.type][0] * t.tier;      // 1->2: base cost, 2->3: twice base cost
        if (gold < uc) continue;
        gold -= uc; t.spent += uc; t.tier += 1;
        t.dmg = tierDamage(t.type, t.tier); t.range = TDEF[t.type][3] + 30 * (t.tier - 1);
        log.push([tick, "U", sl, t.tier]);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
        turrets[sl] = null;
        log.push([tick, "S", sl, 0]);
      }
    }
  }

  function removeDead(slot) {
    // remove every enemy with hp <= 0 in ascending id order, paying bounty and spawning splitlings
    var n = enemies.length, any = false, k;
    for (k = 0; k < n; k++) {
      var e = enemies[k];
      if (e.hp <= 0 && !e.dead) {
        e.dead = true; any = true;
        gold += EDEF[e.type][2];
        log.push([tick, "K", e.id, slot]);
        if (REC && REC.kill) REC.kill(tick, e, slot);
        if (e.type === 4) {
          var hp = Math.max(1, Math.floor(e.maxHp / 4));
          spawnEnemy(6, e.wave, e.progress, hp); spawnEnemy(6, e.wave, e.progress, hp); spawnEnemy(6, e.wave, e.progress, hp);
        }
      }
    }
    if (any) {
      var out = [];
      for (k = 0; k < enemies.length; k++) if (!enemies[k].dead) out.push(enemies[k]);
      enemies = out;
    }
  }

  var tick = 0, fell = false;
  for (tick = 0; tick < maxTicks && !fell; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var st = { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: [], enemies: [], nextWave: [] };
      for (s = 0; s < 16; s++) {
        var tt = turrets[s];
        st.slots.push({ slot: s, x: SLOTS[s][0], y: SLOTS[s][1],
          turret: tt ? { type: TNAMES[tt.type], tier: tt.tier, spent: tt.spent } : null });
      }
      for (i = 0; i < enemies.length; i++) st.enemies.push(view(enemies[i]));
      for (i = 0; i < waves[wave + 1].length; i++) st.nextWave.push(ENAMES[waves[wave + 1][i]]);
      var acts = strategy.plan(st);
      applyActions(acts);
      var comp = waves[wave];
      for (i = 0; i < comp.length; i++) queue.push({ tick: tick + 4 * i, wave: wave, idx: i, type: comp[i] });
      // keep ordered by tick, then wave, then index (stable insertion sort from the tail)
      for (i = queue.length - comp.length; i < queue.length; i++) {
        var q = queue[i], j = i - 1;
        while (j >= qHead && (queue[j].tick > q.tick || (queue[j].tick === q.tick && queue[j].wave > q.wave))) { queue[j + 1] = queue[j]; j--; }
        queue[j + 1] = q;
      }
      if (REC && REC.wave) REC.wave(tick, wave, waves[wave + 1], gold, turrets);
    }
    // 2. spawn
    while (qHead < queue.length && queue[qHead].tick <= tick) {
      var sp = queue[qHead++];
      spawnEnemy(sp.type, sp.wave, 0, Math.floor(EDEF[sp.type][0] * hpMult(sp.wave) / 1000));
    }
    if (qHead > 256) { queue = queue.slice(qHead); qHead = 0; }
    // 3. move
    var leaked = false;
    for (i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      var route = ROUTES[e.air];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= e.len) {
        baseHp -= EDEF[e.type][3];
        e.dead = true; leaked = true;
        log.push([tick, "L", e.id, baseHp]);
        if (REC && REC.leak) REC.leak(tick, e, baseHp);
        if (baseHp <= 0) { fell = true; fallTick = tick; log.push([tick, "F", wave, 0]); break; }
      } else { e.x = route.xs[e.progress]; e.y = route.ys[e.progress]; }
    }
    if (leaked) { var keep = []; for (i = 0; i < enemies.length; i++) if (!enemies[i].dead) keep.push(enemies[i]); enemies = keep; }
    if (fell) { if (REC && REC.tick) REC.tick(tick, enemies, turrets, gold, baseHp, wave, true); break; }
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      var m = enemies[i];
      m.age += 1;
      if (m.type === 5 && m.age % 20 === 0) {
        for (var h = 0; h < enemies.length; h++) {
          var o = enemies[h], dx = o.x - m.x, dy = o.y - m.y;
          if (dx * dx + dy * dy <= 22500) { o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100)); }
        }
        if (REC && REC.heal) REC.heal(tick, m);
      }
    }
    // 5. turrets fire
    for (s = 0; s < 16; s++) {
      var T = turrets[s];
      if (!T) continue;
      if (T.cd > 0) { T.cd -= 1; if (T.cd > 0) continue; }
      var def = TDEF[T.type], r2 = T.range * T.range, cands = [], c;
      for (i = 0; i < enemies.length; i++) {
        c = enemies[i];
        if (c.air ? !def[8] : !def[7]) continue;
        var ddx = c.x - T.x, ddy = c.y - T.y;
        if (ddx * ddx + ddy * ddy <= r2) cands.push(c);
      }
      if (cands.length === 0) continue;
      var tgt = null;
      if (hasTarget) {
        var views = [];
        for (i = 0; i < cands.length; i++) views.push(view(cands[i]));
        var pick = strategy.target({ slot: s, type: TNAMES[T.type], tier: T.tier, x: T.x, y: T.y, range: T.range }, views);
        if (typeof pick === "number") for (i = 0; i < cands.length; i++) if (cands[i].id === pick) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (i = 1; i < cands.length; i++) if (cands[i].len - cands[i].progress < tgt.len - tgt.progress) tgt = cands[i];
      }
      var hits = [];
      if (def[4] > 0) {
        var sr2 = def[4] * def[4], tx = tgt.x, ty = tgt.y;
        for (i = 0; i < enemies.length; i++) {
          c = enemies[i];
          if (c.air ? !def[8] : !def[7]) continue;
          var sx = c.x - tx, sy = c.y - ty;
          if (sx * sx + sy * sy <= sr2) hits.push(c);
        }
      } else hits.push(tgt);
      for (i = 0; i < hits.length; i++) {
        c = hits[i];
        c.hp -= def[6] ? T.dmg : Math.max(1, T.dmg - c.armor);
        if (def[5] > 0) c.slow = def[5];
      }
      T.cd = def[2];
      if (REC && REC.shot) REC.shot(tick, T, tgt, hits);
      removeDead(s);
    }
    // 6. slow timers
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow -= 1;
    if (REC && REC.tick) REC.tick(tick, enemies, turrets, gold, baseHp, wave, false);
  }

  var endTick = fell ? fallTick : maxTicks;
  var str = JSON.stringify(log), hsh = 0x811c9dc5;
  for (i = 0; i < str.length; i++) { hsh ^= str.charCodeAt(i); hsh = Math.imul(hsh, 0x01000193); }
  var hex = (hsh >>> 0).toString(16);
  while (hex.length < 8) hex = "0" + hex;
  return { score: Math.round((endTick - 20) * 100 / 40) / 100, fallTick: fallTick, log: log, hash: hex };
}
if (typeof module !== "undefined") module.exports = rampartSimulate;

