const sim = require("./sim.js");
const COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };

// script: list of [slot, type] entries; each entry = build if empty else upgrade. Executed in order when gold - cost >= reserve(wave)
function scripted(list, reserveFn, targetFn) {
  return () => {
    let idx = 0;
    const tiers = new Array(16).fill(0), types = new Array(16).fill(null);
    const o = {
      plan(s) {
        const acts = []; let g = s.gold;
        while (idx < list.length) {
          const [slot, type] = list[idx];
          let cost;
          if (tiers[slot] === 0) cost = COST[type]; else cost = COST[types[slot]] * tiers[slot];
          if (g - cost < reserveFn(s.wave, s)) break;
          if (tiers[slot] === 0) { acts.push({ op: "build", slot, type }); types[slot] = type; tiers[slot] = 1; }
          else { acts.push({ op: "upgrade", slot }); tiers[slot]++; }
          g -= cost; idx++;
        }
        return acts;
      }
    };
