// coverage lengths per slot/range for ground path and air lane
const GROUND = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
const AIR = [[0, 6], [21, 6], [21, 11], [23, 11]];
const SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
function route(pts) { const xs = [], ys = []; for (let i = 0; i + 1 < pts.length; i++) { const ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50, bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50; const len = Math.abs(bx - ax) + Math.abs(by - ay), sx = Math.sign(bx - ax), sy = Math.sign(by - ay); for (let k = 0; k < len; k++) { xs.push(ax + sx * k); ys.push(ay + sy * k); } if (i + 2 === pts.length) { xs.push(bx); ys.push(by); } } return { xs, ys }; }
const R = [route(GROUND), route(AIR)];
function cov(slot, range, air) { const r = R[air], x = SLOTS[slot][0] * 100 + 50, y = SLOTS[slot][1] * 100 + 50; let n = 0, first = -1, last = -1; for (let p = 0; p < r.xs.length; p++) { const dx = r.xs[p] - x, dy = r.ys[p] - y; if (dx * dx + dy * dy <= range * range) { n++; if (first < 0) first = p; last = p; } } return [n, first, last]; }
console.log("slot  tile     | ground cov @240 260 300 320 360 420 (first-last@300) | air cov @240 300 320 380 (first-last@320)");
for (let s = 0; s < 16; s++) {
  const g = [240, 260, 300, 320, 360, 420].map(r => cov(s, r, 0));
  const a = [240, 300, 320, 380].map(r => cov(s, r, 1));
  console.log(String(s).padStart(2), `(${SLOTS[s]})`.padEnd(8), "|", g.map(v => String(v[0]).padStart(4)).join(" "), ` [${g[2][1]}-${g[2][2]}]`.padEnd(14), "|", a.map(v => String(v[0]).padStart(4)).join(" "), ` [${a[2][1]}-${a[2][2]}]`);
}

