  var RX = [RG[0], RA[0]], RY = [RG[1], RA[1]], RLEN = [4600, 2800];
  var TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
  //           cost dmg period range splash slow pierce ground air
  var TDEF = [[50, 26, 8, 300, 0, 0, 0, 1, 1], [90, 60, 24, 260, 90, 0, 0, 1, 0], [70, 10, 12, 240, 0, 30, 0, 1, 1], [120, 180, 36, 360, 0, 0, 1, 1, 0], [80, 40, 10, 320, 70, 0, 0, 0, 1]];
  var ENAMES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var EIDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
