      T = S.tur[i];
      tur[i] = T === null ? null : { slot: T.slot, type: T.type, tier: T.tier, spent: T.spent, cd: T.cd, dmg: T.dmg, range: T.range, period: T.period, splash: T.splash, slow: T.slow, pierce: T.pierce, covG: T.covG, covA: T.covA };
    }
    return { tick: S.tick, gold: S.gold, base: S.base, nid: S.nid, wave: S.wave, en: out, tur: tur, nm: S.nm, sched: null,
      leakDmg: 0, leakSoft: 0, firstLeak: -1, fall: -1, hpScale: S.hpScale };
  }
  // actions: [op, slot, type]  op 0 build, 1 upgrade, 2 sell
  function applyActs(S, acts) {
    for (var k = 0; k < acts.length && k < 32; k++) {
      var a = acts[k], sl = a[1], T = S.tur[sl];
      if (a[0] === 0) {
