// usage: node run.js [strategyFile] [nSeeds] [jsonOverrides] [verbose]
const sim = require("./sim.js");
const path = require("path");
const mk = require(path.resolve(process.argv[2] || "./strategy.js"));
const nSeeds = +(process.argv[3] || 20);
const ov = process.argv[4] ? JSON.parse(process.argv[4]) : null;
const verbose = process.argv[5] === "v";
const TN = ["bolt", "cannon", "frost", "lance", "flak"];
let sum = 0, tsum = 0, tmax = 0; const scores = [];
for (let i = 1; i <= nSeeds; i++) {
  const seed = 1000 + i * 7;
  let inst = null;
  const t0 = process.hrtime.bigint();
  const r = sim(() => (inst = mk(ov)), seed, 12020);
  const ms = Number(process.hrtime.bigint() - t0) / 1e6;
  sum += r.score; tsum += ms; tmax = Math.max(tmax, ms); scores.push(r.score);
  if (verbose) {
    const lay = new Array(16).fill("--");
    let spent = 0;
    for (const [t, c, a, b] of r.log) { if (c === "B") lay[a] = TN[b][0] + TN[b][1] + "1"; else if (c === "U") lay[a] = lay[a].slice(0, 2) + b; else if (c === "S") lay[a] = "--"; }
    const leaks = r.log.filter(e => e[1] === "L").map(e => e[0]);
    console.log(`seed ${seed} score ${r.score} ms ${ms.toFixed(0)} dbg ${JSON.stringify(inst._dbg)} work ${(inst._work() / 1e6).toFixed(1)}M`);
    console.log("   layout: " + lay.join(" ") + "  leaks@ " + leaks.join(","));
  }
}
console.log(`mean ${(sum / nSeeds).toFixed(3)} min ${Math.min(...scores)} max ${Math.max(...scores)}  avg ms ${(tsum / nSeeds).toFixed(0)} max ms ${tmax.toFixed(0)}`);

