function createStrategy(OV) {
  "use strict";
  // ---------------- parameters ----------------
  var P = {
    H1: 320,            // short (just-in-time) horizon, ticks
    H2: 640,            // long horizon for spending gold above the bank target
    softW: 0.5,         // weight of surviving hp fraction of leakers in J
    pressW: 0.05,       // weight of end-of-horizon pressure
    steps1: 10, steps2: 3,
    bank: 1000,         // gold kept for interest
    relWave: 99,        // from this wave on the bank target is 0
    relFall: 0,         // release the bank when the no-action long sim predicts a fall
    replTier: 1,        // replace candidates for turrets up to this tier
    boltArmCut: 3,
    boltT: [0, 0, 0, 0, 0, 0, 0],      // per enemy type bonus (ticks) for bolt targeting
    lanceT: [0, 0, 0, 0, 0, 0, 0],
    lanceEffW: 60, lanceArmW: 1.0,
    frostT: [0, 0, 0, 0, 0, 0, 0],
    canW: [1, 1, 1, 1, 1, 1, 1],       // per enemy type weight for splash value
    canUrg: 0.0,
    minRatio: 0,        // do not pay more than 1/minRatio gold per unit of J
    budget: 4e8
