// parallel evaluation: node par.js strategyFile nSeeds configsJson [seedBase] [workers]
// configsJson: {"name": {overrides}, ...}  (inline JSON or @file)
const { Worker, isMainThread, parentPort, workerData } = require("worker_threads");
const path = require("path");
const fs = require("fs");
if (!isMainThread) {
  const sim = require("./sim.js");
  const mk = require(workerData.strat);
  parentPort.on("message", (job) => {
    if (job === null) { process.exit(0); }
    let inst = null;
    const t0 = process.hrtime.bigint();
    let r;
    try { r = sim(() => (inst = mk(job.ov)), job.seed, 12020); } catch (e) { parentPort.postMessage({ id: job.id, err: String(e && e.stack || e) }); return; }
    const ms = Number(process.hrtime.bigint() - t0) / 1e6;
    parentPort.postMessage({ id: job.id, score: r.score, ms, dbg: inst && inst._dbg, work: inst && inst._work ? inst._work() : 0 });
  });
} else {
  const strat = path.resolve(process.argv[2]);
  const nSeeds = +process.argv[3];
  let cj = process.argv[4];
  if (cj[0] === "@") cj = fs.readFileSync(cj.slice(1), "utf8");
  const configs = JSON.parse(cj);
  const seedBase = +(process.argv[5] || 5000);
  const nW = +(process.argv[6] || 9);
  const names = Object.keys(configs);
  const jobs = [];
  for (let s = 0; s < nSeeds; s++) for (const n of names) jobs.push({ id: jobs.length, name: n, ov: configs[n], seed: seedBase + s * 13 + 1 });
  const res = {}; for (const n of names) res[n] = { scores: [], ms: [], desync: 0, fb: 0, work: [] };
  let next = 0, done = 0;
  const t0 = Date.now();
  for (let i = 0; i < nW; i++) {
    const w = new Worker(__filename, { workerData: { strat } });
    const give = () => { if (next < jobs.length) w.postMessage(jobs[next++]); else w.postMessage(null); };
    w.on("message", (m) => {
      const job = jobs[m.id];
      if (m.err) { console.error("ERR", job.name, job.seed, m.err); res[job.name].scores.push(0); res[job.name].ms.push(0); }
      else { const r = res[job.name]; r.scores.push(m.score); r.ms.push(m.ms); r.work.push(m.work); if (m.dbg) { r.desync += m.dbg.desyncs || 0; r.fb += m.dbg.fallbacks || 0; } }
      done++;
      if (done === jobs.length) {
        const rows = names.map(n => { const r = res[n], k = r.scores.length; const mean = r.scores.reduce((a, b) => a + b, 0) / k; const sd = Math.sqrt(r.scores.reduce((a, b) => a + (b - mean) ** 2, 0) / k);
          return { n, mean, sd, min: Math.min(...r.scores), max: Math.max(...r.scores), ms: r.ms.reduce((a, b) => a + b, 0) / k, msMax: Math.max(...r.ms), desync: r.desync, fb: r.fb, workMax: Math.max(...r.work) }; });
        rows.sort((a, b) => b.mean - a.mean);
        for (const r of rows) console.log(`${r.mean.toFixed(3)}  sd ${r.sd.toFixed(2)} min ${r.min.toFixed(2)} max ${r.max.toFixed(2)}  ms ${r.ms.toFixed(0)}/${r.msMax.toFixed(0)} workMax ${(r.workMax / 1e6).toFixed(0)}M ${r.desync ? "DESYNC " + r.desync : ""}${r.fb ? " FB " + r.fb : ""}  ${r.n}`);
        console.log(`(${nSeeds} seeds, ${((Date.now() - t0) / 1000).toFixed(1)}s)`);
      }
      give();
    });
    give();
  }
}

