// damage accounting: node stats.js strategyFile seed [overrides]
const fs = require("fs"), path = require("path");
let src = fs.readFileSync(path.join(__dirname, "sim.js"), "utf8");
// inject heal accounting
src = src.replace("if (dx * dx + dy * dy <= 22500) { o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100)); }",
  "if (dx * dx + dy * dy <= 22500) { var __b = o.hp; o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100)); if (REC && REC.healAmt) REC.healAmt(tick, o, o.hp - __b); }");
src = src.replace("c.hp -= def[6] ? T.dmg : Math.max(1, T.dmg - c.armor);",
  "var __d = def[6] ? T.dmg : Math.max(1, T.dmg - c.armor); if (REC && REC.dmg) REC.dmg(tick, T, c, __d, Math.min(__d, c.hp)); c.hp -= __d;");
const m = { exports: {} };
new Function("module", src)(m);
const sim = m.exports;
const mk = require(path.resolve(process.argv[2] || "./strategy.js"));
const seed = +(process.argv[3] || 5001);
const ov = process.argv[4] ? JSON.parse(process.argv[4]) : null;
const TN = ["bolt", "cannon", "frost", "lance", "flak"], EN = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
const W0 = +(process.argv[5] || 30);
const st = { eff: {}, raw: {}, shots: {}, heal: 0, healBy: {}, spawnHp: {}, turTicks: {}, effByE: {}, leakHp: {} };
let curT = null;
sim.recorder = {
  spawn(t, e) { if (e.wave >= W0) st.spawnHp[EN[e.type]] = (st.spawnHp[EN[e.type]] || 0) + e.maxHp; },
  dmg(t, T, c, raw, eff) { if (t < 20 + 40 * (W0 - 1)) return; const k = TN[T.type]; st.eff[k] = (st.eff[k] || 0) + eff; st.raw[k] = (st.raw[k] || 0) + T.dmg; st.effByE[EN[c.type]] = (st.effByE[EN[c.type]] || 0) + eff; },
  shot(t, T) { if (t < 20 + 40 * (W0 - 1)) return; const k = TN[T.type]; st.shots[k] = (st.shots[k] || 0) + 1; },
  healAmt(t, o, a) { if (t < 20 + 40 * (W0 - 1)) return; st.heal += a; st.healBy[EN[o.type]] = (st.healBy[EN[o.type]] || 0) + a; },
  tick(t, enemies, turrets) { if (t < 20 + 40 * (W0 - 1)) return; for (const T of turrets) if (T) { const k = TN[T.type]; st.turTicks[k] = (st.turTicks[k] || 0) + 1 / [8, 24, 12, 36, 10][T.type]; } st.nEn = enemies.length; st.maxEn = Math.max(st.maxEn || 0, enemies.length); },
};
const r = sim(() => mk(ov), seed, 12020);
console.log("score", r.score, "from wave", W0, "max enemies alive", st.maxEn);
for (const k of TN) if (st.shots[k]) console.log(k.padEnd(7), "shots", st.shots[k], "uptime", (st.shots[k] / st.turTicks[k]).toFixed(2), "eff dmg", st.eff[k], "eff/shot", (st.eff[k] / st.shots[k]).toFixed(0), "(base dmg x shots", st.raw[k] ? "" : "", ")");
const totEff = Object.values(st.eff).reduce((a, b) => a + b, 0);
console.log("total eff", totEff, "heal", st.heal, "(" + (100 * st.heal / totEff).toFixed(1) + "% of dmg)", JSON.stringify(st.healBy));
console.log("eff by enemy:", JSON.stringify(st.effByE));
console.log("spawn hp by type (waves>=W0):", JSON.stringify(st.spawnHp));

