const fs = require("fs");
const dir = process.argv[2] || "prof";
const f = fs.readdirSync(dir).filter(x => x.endsWith(".cpuprofile")).sort().pop();
const p = JSON.parse(fs.readFileSync(dir + "/" + f));
const self = {}, byId = {};
for (const n of p.nodes) byId[n.id] = n;
const dt = p.timeDeltas; let tot = 0;
for (let i = 0; i < p.samples.length; i++) { const n = byId[p.samples[i]]; const k = n.callFrame.functionName + ":" + n.callFrame.lineNumber; self[k] = (self[k] || 0) + dt[i]; tot += dt[i]; }
Object.entries(self).sort((a, b) => b[1] - a[1]).slice(0, 12).forEach(([k, v]) => console.log((100 * v / tot).toFixed(1) + "%", k));
const lines = {};
for (const n of p.nodes) if (n.positionTicks) for (const pt of n.positionTicks) { const k = n.callFrame.functionName + ":" + pt.line; lines[k] = (lines[k] || 0) + pt.ticks; }
const lt = Object.values(lines).reduce((a, b) => a + b, 0);
console.log("--- lines");
Object.entries(lines).sort((a, b) => b[1] - a[1]).slice(0, 24).forEach(([k, v]) => console.log((100 * v / lt).toFixed(1) + "%", k));

