for (const bad of ["window", "document", "THREE", "Date", "performance"]) if (new RegExp("\\b" + bad + "\\b").test(strat)) throw new Error("strategy references " + bad);
for (const bad of ["window", "document", "THREE", "AudioContext"]) if (new RegExp("\\b" + bad + "\\b").test(sim)) throw new Error("sim references " + bad);
