// Minimal offscreen WebKit driver for testing: swift wk.swift <file.html> <steps.json> [width height]
// steps: [{"wait": ms} | {"eval": "js"} | {"shot": "out.png"}]
import Cocoa
import WebKit

setvbuf(stdout, nil, _IONBF, 0)
let args = CommandLine.arguments
let fileURL = URL(fileURLWithPath: args[1])
let stepsData = try! Data(contentsOf: URL(fileURLWithPath: args[2]))
let steps = try! JSONSerialization.jsonObject(with: stepsData) as! [[String: Any]]
let W = args.count > 3 ? Double(args[3])! : 1280, H = args.count > 4 ? Double(args[4])! : 650

class Handler: NSObject, WKScriptMessageHandler, WKNavigationDelegate {
  var wv: WKWebView!
  var idx = 0
  func userContentController(_ c: WKUserContentController, didReceive m: WKScriptMessage) { print("[page] \(m.body)") }
  func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) { print("[driver] didFinish"); DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { self.next() } }
  func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) { print("[driver] didFail \(error)"); exit(2) }
  func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) { print("[driver] didFailProvisional \(error)"); exit(2) }
  func webViewWebContentProcessDidTerminate(_ webView: WKWebView) { print("[driver] web content process terminated"); exit(3) }
  func next() {
    if idx >= steps.count { print("[driver] done"); exit(0) }
    let s = steps[idx]; idx += 1
    if let ms = s["wait"] as? Double { DispatchQueue.main.asyncAfter(deadline: .now() + ms / 1000.0) { self.next() } }
    else if let js = s["eval"] as? String {
      wv.evaluateJavaScript(js) { r, e in
        if let e = e { print("[eval error] \(e.localizedDescription) :: \((e as NSError).userInfo["WKJavaScriptExceptionMessage"] ?? "")") } else if let r = r { print("[eval] \(r)") } else { print("[eval] (void)") }
        self.next()
      }
    } else if let path = s["shot"] as? String {
      let cfg = WKSnapshotConfiguration()
      wv.takeSnapshot(with: cfg) { img, e in
        if let img = img, let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) {
          try? png.write(to: URL(fileURLWithPath: path)); print("[shot] \(path) \(rep.pixelsWide)x\(rep.pixelsHigh)")
        } else { print("[shot error] \(String(describing: e))") }
        self.next()
      }
    } else { next() }
  }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
let cfg = WKWebViewConfiguration()
let h = Handler()
cfg.userContentController.add(h, name: "log")
let hook = """
(function(){
  function send(t, a){ try { window.webkit.messageHandlers.log.postMessage(t + ' ' + Array.prototype.map.call(a, function(x){ try { return typeof x === 'string' ? x : JSON.stringify(x); } catch(e) { return String(x); } }).join(' ')); } catch(e) {} }
  ['log','warn','error','info'].forEach(function(k){ var o = console[k]; console[k] = function(){ send(k.toUpperCase(), arguments); if (o) o.apply(console, arguments); }; });
  window.addEventListener('error', function(e){ send('UNCAUGHT', [e.message, (e.filename||'') + ':' + e.lineno + ':' + e.colno]); });
  window.addEventListener('unhandledrejection', function(e){ send('REJECTION', [String(e.reason)]); });
})();
"""
cfg.userContentController.addUserScript(WKUserScript(source: hook, injectionTime: .atDocumentStart, forMainFrameOnly: true))
cfg.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
let wv = WKWebView(frame: NSRect(x: 0, y: 0, width: W, height: H), configuration: cfg)
h.wv = wv
wv.navigationDelegate = h
let win = NSWindow(contentRect: NSRect(x: -4000, y: -4000, width: W, height: H), styleMask: [.borderless], backing: .buffered, defer: false)
win.contentView = wv
win.orderFrontRegardless()
wv.loadFileURL(fileURL, allowingReadAccessTo: fileURL.deletingLastPathComponent())
DispatchQueue.main.asyncAfter(deadline: .now() + 240) { print("[driver] timeout"); exit(4) }
app.run()

