    let s = steps[idx]; idx += 1
    if let ms = s["wait"] as? Double { DispatchQueue.main.asyncAfter(deadline: .now() + ms / 1000.0) { self.next() } }
    else if let js = s["eval"] as? String {
      wv.evaluateJavaScript(js) { r, e in
        if let e = e { print("[eval error] \(e.localizedDescription) :: \((e as NSError).userInfo["WKJavaScriptExceptionMessage"] ?? "")") } else if let r = r { print("[eval] \(r)") } else { print("[eval] (void)") }
        self.next()
      }
    } else if let path = s["shot"] as? String {
      let cfg = WKSnapshotConfiguration()
      wv.takeSnapshot(with: cfg) { img, e in
        if let img = img, let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) {
          try? png.write(to: URL(fileURLWithPath: path)); print("[shot] \(path) \(rep.pixelsWide)x\(rep.pixelsHigh)")
        } else { print("[shot error] \(String(describing: e))") }
        self.next()
      }
    } else { next() }
  }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
let cfg = WKWebViewConfiguration()
let h = Handler()
cfg.userContentController.add(h, name: "log")
let hook = """
(function(){
  function send(t, a){ try { window.webkit.messageHandlers.log.postMessage(t + ' ' + Array.prototype.map.call(a, function(x){ try { return typeof x === 'string' ? x : JSON.stringify(x); } catch(e) { return String(x); } }).join(' ')); } catch(e) {} }
  ['log','warn','error','info'].forEach(function(k){ var o = console[k]; console[k] = function(){ send(k.toUpperCase(), arguments); if (o) o.apply(console, arguments); }; });
  window.addEventListener('error', function(e){ send('UNCAUGHT', [e.message, (e.filename||'') + ':' + e.lineno + ':' + e.colno]); });
  window.addEventListener('unhandledrejection', function(e){ send('REJECTION', [String(e.reason)]); });
})();
"""
cfg.userContentController.addUserScript(WKUserScript(source: hook, injectionTime: .atDocumentStart, forMainFrameOnly: true))
