    var s, t, i, cands = [], basic = 0, lk = cur.lk, pG = 1e9, pA = 1e9;
    // where are the predicted leakers now? (not yet spawned = start of the route)
    for (i = 0; i < lk.length; i += 2) { var pr = progOf(lk[i], lk[i + 1]); if (lk[i + 1]) { if (pr < pA) pA = pr; } else if (pr < pG) pG = pr; }
